#include <vector>

class Solution {
public:
    int getSum(std::vector<int>& nums) {
        long long MOD = 1000000007;
        int n = nums.size();
        if (n == 0) return 0;

        auto sum_consecutive = [&](int diff) {
            long long total = 0;
            long long curr_sum = nums[0];
            long long curr_cnt = 1;
            total = (total + curr_sum) % MOD;

            for (int i = 1; i < n; ++i) {
                if (nums[i] - nums[i - 1] == diff) {
                    curr_sum = (curr_sum + (long long)nums[i] * (curr_cnt + 1)) % MOD;
                    curr_cnt++;
                } else {
                    curr_sum = nums[i];
                    curr_cnt = 1;
                }
                total = (total + curr_sum) % MOD;
            }
            return total;
        };

        long long inc_sum = sum_consecutive(1);
        long long dec_sum = sum_consecutive(-1);
        long long singles = 0;
        for (int x : nums) singles = (singles + x) % MOD;

        long long ans = (inc_sum + dec_sum - singles) % MOD;
        if (ans < 0) ans += MOD;
        return ans;
    }
};

class Solution {
    public int getSum(int[] nums) {
        long MOD = 1_000_000_007L;
        int n = nums.length;
        if (n == 0) return 0;

        long incSum = sumConsecutive(nums, 1, MOD);
        long decSum = sumConsecutive(nums, -1, MOD);
        long singles = 0;
        for (int x : nums) singles = (singles + x) % MOD;

        long ans = (incSum + decSum - singles) % MOD;
        if (ans < 0) ans += MOD;
        return (int) ans;
    }

    private long sumConsecutive(int[] nums, int diff, long MOD) {
        long total = 0;
        long currSum = nums[0];
        long currCnt = 1;
        total = (total + currSum) % MOD;

        for (int i = 1; i < nums.length; i++) {
            if (nums[i] - nums[i - 1] == diff) {
                currSum = (currSum + (long) nums[i] * (currCnt + 1)) % MOD;
                currCnt++;
            } else {
                currSum = nums[i];
                currCnt = 1;
            }
            total = (total + currSum) % MOD;
        }
        return total;
    }
}

